const durum = { sinav: 'yaklasan', kasa: 'hareket', filo: 'arac', mesaj: 'gelen', meb: 'aktarim', ayar: 'kurs' };
let secSohbet = null, gecmisKim = '', sohbetAcik = false;

/* ================= SINAVLAR ================= */
export function sinavlar(alt) {
  if (['yaklasan', 'gecmis', 'risk', 'yol'].includes(alt)) durum.sinav = alt;
  const gec = sbSinav(S.sinavlar).filter(s => Object.keys(s.sonuc || {}).length);
  const oran = tur => { const l = gec.filter(s => s.tur === tur).flatMap(s => Object.values(s.sonuc || {})); return l.length ? Math.round(l.filter(x => x === 'Geçti').length / l.length * 100) : 0; };
  const kalanlar = sb(S.kursiyerler).filter(k => k.dsinav && k.dsinav.sonuc === 'Kaldı');
  const riskli = sb(S.kursiyerler).map(k => ({ k, r: risk(k) })).filter(x => x.r && x.r.puan >= 25).sort((a, b) => b.r.puan - a.r.puan);
  const liste = sbSinav(S.sinavlar).filter(s => durum.sinav === 'yaklasan' ? fark(s.tarih) >= 0 : fark(s.tarih) < 0).sort((a, b) => durum.sinav === 'yaklasan' ? a.tarih.localeCompare(b.tarih) : b.tarih.localeCompare(a.tarih));
  const kartSinav = s => {
    const ks = s.kursiyerler.map(kursiyer).filter(Boolean), sonucVar = Object.keys(s.sonuc || {}).length;
    const gecen = Object.values(s.sonuc || {}).filter(x => x === 'Geçti').length;
    return `<div class="kart"><div class="kart-bas" style="padding-bottom:4px"><span class="oto-ik">${ik(s.tur === 'e-Sınav' ? 'teorik' : 'direksiyon')}</span><div><h3>${s.tur} · ${tarihUzun(s.tarih)}</h3><small>${s.saat} · ${e(s.yer)}</small></div>
      <div class="sag">${sonucVar ? rozet(`${gecen}/${ks.length} geçti`, gecen / ks.length > .7 ? 'yesil' : 'turuncu') : rozet(goreli(s.tarih), fark(s.tarih) <= 3 ? 'sari' : 'mavi')}</div></div>
      <ul class="liste" style="margin-top:6px">${ks.slice(0, 6).map(k => `<li><a class="kisi" href="#/kursiyer/${k.id}" style="flex:1">${avatar(k.ad, k.soyad, k.foto)}<div><b>${e(tamAd(k))}</b><small>${SINIFLAR[k.sinif].ad}${k.dsinav && k.dsinav.sonuc === 'Kaldı' && !s.sonuc[k.id] ? ' · ' + (k.dsinav.hak + 1) + '. hak' : ''}</small></div></a><span class="sag">${s.sonuc[k.id] ? rozet(s.sonuc[k.id], s.sonuc[k.id] === 'Geçti' ? 'yesil' : 'kirmizi') : ''}</span></li>`).join('') || '<li>' + bos('Bu oturuma kursiyer eklenmedi', '') + '</li>'}
        ${ks.length > 6 ? `<li style="color:var(--soluk);font-size:13px">+${ks.length - 6} kursiyer daha</li>` : ''}</ul>
      <div style="display:flex;gap:8px;padding:12px 20px 16px;border-top:1px solid var(--cizgi-2);flex-wrap:wrap">
        ${fark(s.tarih) <= 0 && !sonucVar ? `<button class="dg dg-ana dg-kucuk" data-sonuc="${s.id}">Sonuçları gir</button>` : ''}
        ${sonucVar ? `<button class="dg dg-cizgi dg-kucuk" data-sonuc-duzelt="${s.id}">${ik('kalem')}Sonucu düzelt</button>` : ''}
        ${fark(s.tarih) <= 0 && !sonucVar ? `<button class="dg dg-cizgi dg-kucuk" data-meb-cekbtn="sinav" title="Yardımcı MEBBİS’teki sonuç listesini alıp bu pencereye doldurur">${ik('indir')}Sonuçları MEBBİS’ten al</button>` : ''}
        ${(() => { const ids = s.tur === 'Direksiyon' && fark(s.tarih) >= 0 ? EKL.mebIsleri().filter(x => x.tur === 'sinav' && x.ref.sinav === s.id).map(x => x.id) : []; return ids.length ? `<button class="dg dg-ana dg-kucuk" data-meb-gonder="${ids.join(',')}">MEBBİS’e bildir (${ids.length})</button>` : ''; })()}
        ${fark(s.tarih) >= 0 ? `<button class="dg dg-cizgi dg-kucuk" data-ekle="${s.id}">${ik('arti')}Kursiyer ekle</button><button class="dg dg-wp dg-kucuk" data-hatir="${s.id}">${ik('wp')}Hepsine hatırlat</button>` : ''}
        <button class="dg dg-hafif dg-kucuk" data-liste="${s.id}">${ik('indir')}Listeyi indir</button>
        ${s.tur === 'Direksiyon' && fark(s.tarih) >= 0 && ks.length ? (s.ucretMem ? `<button class="dg dg-hafif dg-kucuk" data-ucret-mem="${s.id}" title="İşareti kaldır">${ik('tik')}Ücret makbuzu MEM’e verildi · ${tarih(s.ucretMem)}</button>` : mebIsGunuSay(gun(0), s.tarih) <= kuralAyar('sinavUcretIsGunu') + 2 ? `<button class="dg dg-cizgi dg-kucuk" data-ucret-mem="${s.id}" title="Sınav ücretleri sınavdan ${kuralAyar('sinavUcretIsGunu')} iş günü önce yatırılır; liste ve makbuz il/ilçe MEM’e verilir (MTSK md.43/5)">Makbuz MEM’e verildi (son gün ${tarih(mebIsGunuGeri(s.tarih, kuralAyar('sinavUcretIsGunu')))})</button>` : '') : ''}
      </div></div>`;
  };
  return {
    baslik: 'Sınavlar', alt: 'e-Sınav ve uygulama sınavı oturumları',
    html: `${ekranNotu('Sınav günleri, kimlerin gireceği ve sonuçlar. “Kalma riski” sekmesi kalabilecek kursiyeri önceden gösterir; ek ders önerip hem kursiyeri hem geliri kurtarın.')}<div class="izgara iz-4">
      <div class="kart gosterge"><small>e-Sınav geçme oranı</small><b>%${oran('e-Sınav')}</b><span>Son oturumlar</span></div>
      <div class="kart gosterge"><small>Direksiyon geçme oranı</small><b>%${oran('Direksiyon')}</b><span>Son oturumlar</span></div>
      <div class="kart gosterge"><small>Sınava hazır</small><b>${sb(S.kursiyerler).filter(k => k.asama === 'Sınav' && !k.dsinav && !k.dsinavPlan).length}</b><span>Direksiyon derslerini bitirdi, oturum bekliyor</span></div>
      <div class="kart gosterge"><small>Tekrar sınava girecek</small><b>${kalanlar.length}</b><span>${(() => { const t = kalanlar.filter(k => k.ekDersTeklif).length, y = kalanlar.filter(k => S.sinavlar.some(s => s.tur === 'Direksiyon' && fark(s.tarih) >= 0 && s.kursiyerler.includes(k.id))).length; return kalanlar.length ? `${y} kişi yeni oturuma yazıldı · ${t} kişiye ek ders teklif edildi` : 'Kalan kursiyer yok'; })()}</span></div>
    </div><div class="ara-bosluk"></div>
    <div class="bolum-bas"><div id="sek">${sekmeler([['yaklasan', 'Yaklaşan', sbSinav(S.sinavlar).filter(s => fark(s.tarih) >= 0).length], ['gecmis', 'Geçmiş', sbSinav(S.sinavlar).filter(s => fark(s.tarih) < 0).length], ['yol', 'e-Sınav yolu', TY.yolAdaylari().filter(k => !['muaf', 'gecti'].includes(TY.esinavAsamasi(k))).length], ['risk', 'Kalma riski', riskli.length], ['deneme', 'Deneme başarısı', denemeOzet().filter(x => x.n && x.oran < 70).length]], durum.sinav)}</div><div class="sag"><button class="dg dg-ana" data-yeni>${ik('arti')}Sınav oturumu ekle</button></div></div>
    ${durum.sinav === 'yol' ? TY.yolHtml() : durum.sinav === 'deneme' ? denemeHtml() : durum.sinav === 'risk' ? `<div class="kart"><div class="kart-bas"><h3>Sınavda kalabilecek kursiyerler</h3><small>Usta öğreticinin ders sonu beceri puanları, deneme sınavları, devamsızlık ve önceki sonuçlardan hesaplanır</small>${riskli.some(x => x.r.puan >= 50 && x.r.oneri && !x.k.ekDersTeklif) ? `<div class="sag"><button class="dg dg-wp dg-kucuk" data-toplu-ekders>${ik('wp')}Yüksek risklilere ek ders teklif et</button></div>` : ''}</div><ul class="liste" style="margin-top:8px">${riskli.map(({ k, r }) => `<li>${isaret(r.puan >= 50 ? 'uyari' : 'bilgi', 28)}<a class="kisi" href="#/kursiyer/${k.id}" style="flex:1"><div><b>${e(tamAd(k))} · ${r.seviye} risk · ${r.puan}/100</b><small>${r.tur} · ${e(r.nedenler.join(' · '))}</small></div></a><span class="sag">${k.ekDersTeklif ? rozet(k.ekDersTeklif.n + ' ders teklif edildi', 'mavi') : `<button class="dg dg-ana dg-kucuk" data-ekders="${k.id}">Ek ders öner</button>`}</span></li>`).join('') || '<li>' + bos('Riskli kursiyer yok', 'Herkes sınava hazır görünüyor.') + '</li>'}</ul></div>` : `<div class="izgara iz-2">${liste.map(kartSinav).join('') || `<div class="kart">${bos('Oturum yok', 'Yeni bir sınav oturumu ekleyin.')}</div>`}</div>`}`,
    baglan(k) {
      if (durum.sinav === 'yol') TY.yolBaglan(k, yenile, { oturumaEkle: tekOturumaEkle, sonucGir });
      // deneme başarısı süzgeci ve arama (UYG-005): tablo yerinde yeniden çizilir, odak kaybolmaz
      k.addEventListener('input', ev => { const t = ev.target; if (t.matches('[data-dn-ara]')) { dnSuz.ara = t.value; const y = k.querySelector('[data-dn-tablo]'); if (y) y.innerHTML = denemeTablo(); } if (t.matches('[data-dn-suz]')) { dnSuz.suz = t.value; const y = k.querySelector('[data-dn-tablo]'); if (y) y.innerHTML = denemeTablo(); } });
      k.addEventListener('click', ev => {
        const t = ev.target;
        const s = t.closest('[data-sekme]'); if (s) { durum.sinav = s.dataset.sekme; yenile(); }
        if (t.closest('[data-yeni]')) oturumEkle();
        const ed = t.closest('[data-ekders]'); if (ed) ekDersOner(kursiyer(ed.dataset.ekders));
        if (t.closest('[data-toplu-ekders]')) {
          const l = riskli.filter(x => x.r.puan >= 50 && x.r.oneri && !x.k.ekDersTeklif);
          l.forEach(({ k, r }) => { k.ekDersTeklif = { n: r.oneri, tutar: r.oneri * ekDersFiyat(k.sinif), tarih: gun(0), neden: 'risk' }; });
          islem('Riskli kursiyerlere ek ders teklif etti', l.length + ' kursiyer'); kaydet(); yenile();
          waSirali(l.map(({ k, r }) => { const a = alici(k); return { ad: a.ad, tel: a.tel, rol: a.rol, tur: 'Ek ders teklifi', metin: `${selam(k)} son derslerinize göre ${r.tur.toLocaleLowerCase('tr')} öncesi ${r.oneri} ek direksiyon dersi (${tl(r.oneri * S.kurs.ekDersUcreti)}) öneriyoruz${r.beceri && r.beceri.zayif.length ? '; özellikle ' + r.beceri.zayif.join(', ').toLocaleLowerCase('tr') + ' üzerinde çalışacağız' : ''}. Kursiyer ekranından ya da bu mesaja “evet” yazarak onaylayabilirsiniz.` }; }), 'Ek ders teklifi');
        }
        const so = t.closest('[data-sonuc]'); if (so) sonucGir(S.sinavlar.find(x => x.id === so.dataset.sonuc));
        const sd = t.closest('[data-sonuc-duzelt]'); if (sd) sonucDuzeltListe(S.sinavlar.find(x => x.id === sd.dataset.sonucDuzelt));
        const ek = t.closest('[data-ekle]'); if (ek) sinavaEkle(S.sinavlar.find(x => x.id === ek.dataset.ekle));
        const h = t.closest('[data-hatir]'); if (h) { const s2 = sbSinav(S.sinavlar).find(x => x.id === h.dataset.hatir); const ml = k => `${selam(k)} ${s2.tur === 'e-Sınav' ? 'e-sınavınız' : 'uygulama sınavınız'} ${tarihUzun(s2.tarih)} ${saatDe(adaySinavSaati(s2, k).saat)}, yer: ${s2.yer}. Kimliğinizi yanınıza almayı unutmayın. Başarılar!`; const l = s2.kursiyerler.map(kursiyer).filter(Boolean); waSirali(kisiListe(l, ml), s2.tur + ' hatırlatması'); }
        const um = t.closest('[data-ucret-mem]'); if (um) { const s2 = S.sinavlar.find(x => x.id === um.dataset.ucretMem); if (s2) { s2.ucretMem = s2.ucretMem ? null : gun(0); islem(s2.ucretMem ? 'Sınav ücreti makbuzunu MEM’e verdi' : 'Makbuz işaretini kaldırdı', s2.tur + ' · ' + tarih(s2.tarih)); kaydet(); bildir(s2.ucretMem ? 'Kaydedildi: sınav ücreti makbuzu MEM’e verildi' : 'İşaret kaldırıldı'); yenile(); } return; }
        const l = t.closest('[data-liste]'); if (l) { const s2 = sbSinav(S.sinavlar).find(x => x.id === l.dataset.liste); csvIndir(`sinav-${s2.tur}-${s2.tarih}.csv`, [['Ad', 'Soyad', 'Telefon', 'Sınıf', 'Sonuç'], ...s2.kursiyerler.map(kursiyer).map(x => [x.ad, x.soyad, x.tel, SINIFLAR[x.sinif].ad, s2.sonuc[x.id] || ''])]); bildir('Sınav listesi indirildi'); }
      });
    },
  };
}
export function oturumEkle() {
  pencere({
    baslik: 'Sınav oturumu ekle',
    icerik: `<form class="form-izgara" id="f-sinav"><div class="alan tam"><span class="et">Sınav türü</span><div class="secim"><label><input type="radio" name="tur" value="e-Sınav" checked><span>e-Sınav</span></label><label><input type="radio" name="tur" value="Direksiyon"><span>Uygulama sınavı</span></label></div></div>
      <div class="alan"><label>Tarih</label><input type="date" name="tarih" value="${gun(7)}" required></div><div class="alan"><label>Saat</label><input type="time" name="saat" value="09:00" required></div>
      <div class="alan tam"><label>Yer</label><input name="yer" value="${e(((S.sinavlar || []).slice().sort((a, b) => b.tarih.localeCompare(a.tarih)).find(x => x.yer) || {}).yer || '')}" placeholder="Örn. ${e(S.kurs.sehir || '')} e-Sınav Merkezi" required></div></form>
      <p style="font-size:12.5px;color:var(--soluk);margin-top:12px">Tarihi MEB’den gelen sınav takvimine göre girin; kursiyerleri sonra ekleyebilirsiniz.</p>`,
    altlik: `<button class="dg dg-cizgi" data-kapat>Vazgeç</button><button class="dg dg-ana" type="submit" form="f-sinav">Oturumu ekle</button>`,
    onAc(d) {
      const f = d.querySelector('form');
      f.addEventListener('change', () => { if (f.tur.value === 'Direksiyon' && f.yer.value.includes('e-Sınav')) f.yer.value = 'Sınav güzergâhı · Organize Sanayi'; });
      f.addEventListener('submit', ev => { ev.preventDefault(); const kg = kapaliGun(f.tarih.value); if (kg && !f.dataset.onay) { f.dataset.onay = '1'; return bildir(`${tarihUzun(f.tarih.value)} ${kg.toLowerCase()}. Tarih MEB takviminden doğruysa yeniden “Oturumu ekle”ye basın.`, 'uyari'); } S.sinavlar.push({ id: 's' + Date.now(), tur: f.tur.value, tarih: f.tarih.value, saat: f.saat.value, yer: f.yer.value, kursiyerler: [], sonuc: {} }); kaydet(); kapatPencere(); bildir('Sınav oturumu eklendi'); durum.sinav = 'yaklasan'; yenile(); });
    },
  });
}
// Otomatik mesaj kuralı açık mı (Mesajlar › Otomatik mesajlar)
const kuralAcik = id => (S.otomasyonlar.find(o => o.id === id) || {}).acik !== false;
// Sınav ücreti oturuma yazılınca eklenir: e-sınav her oturumda, uygulama sınavı tekrarda
// e-Sınav yolundan tek adayı yaklaşan e-sınav oturumuna ekler (TEO-007); oturum yoksa yeni oturum açtırır
function tekOturumaEkle(k) {
  if (!k) return;
  const l = sbSinav(S.sinavlar).filter(s => s.tur === 'e-Sınav' && fark(s.tarih) >= 0 && !(s.kursiyerler || []).includes(k.id)).sort((a, b) => a.tarih.localeCompare(b.tarih));
  if (!l.length) return pencere({ baslik: 'e-Sınav oturumu yok', icerik: `<p>${e(tamAd(k))} için yaklaşan e-sınav oturumu yok. MEBBİS’te başvurusunu yapıp verilen randevuyu oturum olarak ekleyin.</p>`, altlik: `<button class="dg dg-cizgi" data-kapat>Kapat</button><button class="dg dg-ana" data-yeni-ot>${ik('arti')}Yeni oturum</button>`, onAc(d) { d.querySelector('[data-yeni-ot]').addEventListener('click', () => { kapatPencere(); oturumEkle(); }); } });
  pencere({
    baslik: tamAd(k) + ' · e-sınav oturumu',
    icerik: `<div class="secim" style="display:grid;gap:8px">${l.map((s, i) => `<label><input type="radio" name="o" value="${s.id}" ${i ? '' : 'checked'}><span>${tarihUzun(s.tarih)} ${e(s.saat || '')} · ${e(s.yer || '')} · ${(s.kursiyerler || []).length} kişi</span></label>`).join('')}</div>`,
    altlik: `<button class="dg dg-cizgi" data-kapat>Vazgeç</button><button class="dg dg-ana" data-ekle-ot>Ekle</button>`,
    onAc(d) { d.querySelector('[data-ekle-ot]').addEventListener('click', () => { const s = S.sinavlar.find(x => x.id === (d.querySelector('[name=o]:checked') || {}).value); if (!s) return; s.kursiyerler.push(k.id); sinavUcreti(k, s); islem('Sınava kursiyer yazdı', 'e-Sınav · ' + tarih(s.tarih) + ' · ' + tamAd(k)); kaydet(); kapatPencere(); bildir(`${tamAd(k)} ${tarih(s.tarih)} e-sınav oturumuna eklendi`, 'tamam'); yenile(); }); },
  });
}
function sinavUcreti(k, s) {
  const es = s.tur === 'e-Sınav', o = es ? k.esinav : k.dsinav, hak = (o && o.sonuc !== 'Geçti' ? o.hak : 0) + 1;
  const tutar = es ? esinavUcreti(hak) : uygulamaSinavUcreti(hak);
  k.odeme.ekler = k.odeme.ekler || [];
  if (!tutar || k.odeme.ekler.some(x => x.sinav === s.id)) return;
  k.odeme.ekler.push({ ad: `${es ? 'e-Sınav ücreti' : 'Uygulama sınavı ücreti'} (${hak}. sınav · ${tarih(s.tarih)})`, tutar, odendi: null, sinav: s.id, tur: 'resmi' });  // resmî masraf: kurs ücretine eklenmez, emanet (il taban listesi notu 5, MTSK md.43/5)
}
// Sınava yazılan kursiyere randevu bilgisi, uygulama sınavında hocasına liste
