// Yanlış tahsilat: silinmez, ters kayıtla iptal edilir. Kursiyerin borcu geri açılır (tahsilatın dağıldığı taksitler biliniyorsa onlar,
// bilinmiyorsa aynı tutarda yeni açık taksit), kasaya "Tahsilat iptali" gideri düşer, makbuz iptal olarak işaretlenir; işlem kayda yazılır.
function tahsilatIptal(h) {
  const k = kursiyer(h.kursiyer); if (!k || h.iptal || !mudurMu()) return;
  pencere({ baslik: 'Tahsilatı iptal et', icerik: `<p style="font-size:14.5px"><b>${e(tamAd(k))}</b> · ${tl(h.tutar)} · ${e(h.no || '')} · ${tarih(h.tarih)}</p>
      <div class="alan" style="margin-top:12px"><label>Neden</label><select name="n"><option>Yanlış tutar girildi</option><option>Yanlış öğrenciye girildi</option><option>Ödeme gerçekleşmedi (kart/havale geri döndü)</option><option>Mükerrer kayıt</option><option>Diğer</option></select></div>
      <p style="font-size:13.5px;color:var(--soluk);margin-top:10px">Öğrencinin borcu geri açılır, kasaya aynı tutarda "Tahsilat iptali" düşer, makbuz iptal olarak işaretlenir. Kayıt silinmez, işlem geçmişine yazılır.</p>`,
    altlik: '<button class="dg dg-cizgi" data-kapat>Vazgeç</button><button class="dg dg-ana" data-onay style="background:var(--kirmizi);border-color:var(--kirmizi)">Tahsilatı iptal et</button>',
    onAc(p) { p.querySelector('[data-onay]').addEventListener('click', () => {
      const neden = p.querySelector('[name=n]').value, v = h.tutar; geriAlNoktasi();
      let geri = false;
      // ek kalem tahsilatı (ek ders, sınav ücreti): kalem yeniden ödenmemiş olur
      { const x = (k.odeme.ekler || []).find(y => y.ad === h.kategori && y.odendi && +y.tutar === +v); if (x) { x.odendi = null; geri = true; } }
      if (h.kategori === 'Peşinat' && (k.odeme.pesin || 0) >= v) { k.odeme.pesin -= v; k.odeme.taksitler.push({ vade: gun(0), tutar: v, odendi: null, yontem: null, aciklama: 'İptal edilen peşinat' }); geri = true; }
      else if (Array.isArray(h.dagilim) && h.dagilim.length && h.dagilim.every(x => k.odeme.taksitler[x.i] && k.odeme.taksitler[x.i].vade === x.vade)) {
        h.dagilim.forEach(x => { const t = k.odeme.taksitler[x.i], odenmis = t.odendi ? t.tutar : (t.kismi || 0), kalan = Math.max(0, odenmis - x.al); t.odendi = null; t.yontem = null; if (kalan > 0) t.kismi = kalan; else delete t.kismi; });
        geri = true;
      }
      if (!geri) {  // dağılım bilinmiyor (eski kayıt): ödenmiş taksitler, tahsilat günündekilerden başlayarak en yeniden geriye açılır
        let kalanV = v; const odenmis = k.odeme.taksitler.filter(t => t.odendi || t.kismi).sort((a, b) => ((b.odendi === h.tarih) - (a.odendi === h.tarih)) || String(b.odendi || '').localeCompare(String(a.odendi || '')));
        for (const t of odenmis) { if (!kalanV) break; const odenen = t.odendi ? t.tutar : (t.kismi || 0), al = Math.min(odenen, kalanV), kal = odenen - al; kalanV -= al; t.odendi = null; t.yontem = null; if (kal > 0) t.kismi = kal; else delete t.kismi; }
        if (kalanV > 0 && (k.odeme.pesin || 0) >= kalanV) { k.odeme.pesin -= kalanV; k.odeme.taksitler.push({ vade: gun(0), tutar: kalanV, odendi: null, yontem: null, aciklama: 'İptal edilen tahsilat ' + (h.no || '') }); }
      }
      h.iptal = { tarih: gun(0), neden, kim: oturum.kullanici ? oturum.kullanici.ad : '' };
      S.hareket.unshift({ id: 'h' + Date.now(), tarih: gun(0), tur: 'Gider', kategori: 'Tahsilat iptali', aciklama: tamAd(k) + ' · ' + (h.no || '') + ' iptal · ' + neden, tutar: v, yontem: h.yontem, kursiyer: k.id, iptalEdilen: h.id });
      islem('Tahsilatı iptal etti', tamAd(k) + ' · ' + (h.no || '') + ' · ' + tl(v) + ' · ' + neden);
      kaydet(); kapatPencere(); bildir('Tahsilat iptal edildi; öğrencinin borcu geri açıldı'); yenile();
    }); } });
}
